 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = max((v for v in counts if v != bg), key=lambda v: counts[v])
    cells = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == color]
    r0,r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0,c1 = min(c for r,c in cells), max(c for r,c in cells)
    # Fill missing cells on the bounding rectangle's perimeter in accent color.
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if grid[r][c] == bg:
                out[r][c] = 2
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if grid[r][c] == bg:
                out[r][c] = 2
    return out

if __name__ == '__main__':
    t=[[1]*12 for _ in range(29)]
